import org.junit.Test;
import static org.junit.Assert.*;
import org.jsoup.nodes.TextNode;
import org.jsoup.nodes.Element;

public class TextNodeTest {

    @Test
    public void newTextNode_GivenText_ReturnsTextNode() {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        assertNotNull(node);
        assertEquals(text, node.text());
    }

    @Test
    public void nodeName_ReturnsCorrectValue() {
        TextNode node = new TextNode("");
        assertEquals("#text", node.nodeName());
    }

    @Test
    public void text_GivenText_ReturnsUnencodedText() {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        assertEquals(text, node.text());
    }

    @Test
    public void text_GivenEncodedText_ReturnsUnencodedText() throws IOException {
        String encodedText = "&lt;Hello&gt; World";
        TextNode node = TextNode.createFromEncoded(encodedText);
        assertEquals(" < Hello > World", node.text());
    }

    @Test
    public void isBlank_GivenText_ReturnsFalse() {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        assertFalse(node.isBlank());
    }

    @Test
    public void isBlank_GivenEmptyString_ReturnsTrue() {
        TextNode node = new TextNode("");
        assertTrue(node.isBlank());
    }

    @Test
    public void splitText_GivenOffset_ReturnsCorrectTextNode() throws IOException {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        int offset = 6;
        TextNode tailNode = node.splitText(offset);
        assertEquals("World", tailNode.text());
    }

    @Test
    public void splitText_GivenInvalidOffset_ThrowsException() {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        int offset = -1;
        try {
            node.splitText(offset);
            fail("Expected IndexOutOfBoundsException");
        } catch (IndexOutOfBoundsException e) {
            // expected
        }
    }

    @Test
    public void clone_ReturnsCorrectTextNode() {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        TextNode cloned = node.clone();
        assertNotNull(cloned);
        assertEquals(text, cloned.text());
    }

    @Test
    public void toString_ReturnsOuterHtml() throws IOException {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        String outerHtml = node.toString();
        assertNotNull(outerHtml);
    }
}
